#include <bits/stdc++.h>
using namespace std;
#define MODUL 1000000007
#define MAX_SIZE 33
#define long long ll
ll binary[MAX_SIZE*2], n_value, m_value;

struct MatrixType {
    ll matrix[MAX_SIZE][MAX_SIZE];
    inline MatrixType multiply(const MatrixType &other) const {
        MatrixType result;
        memset(result.matrix, 0, sizeof(result.matrix));
        for (int i=0; i<=m_value; ++i) {
            for (int j=0; j<=m_value; ++j) {
                for (int k=0; k<=m_value; ++k) {
                    result.matrix[i][j] = (result.matrix[i][j] + matrix[i][k] * other.matrix[k][j]) % MODUL;
                }
            }
        }
        return result;
    }
};

int get_input() {
    int x=0, sign=1;
    char ch=getchar();
    while (ch<'0' || ch>'9') {
        if (ch=='-') sign=-1;
        ch=getchar();
    }
    while (ch>='0' && ch<='9') {
        x=x*10+ch-'0'; ch=getchar();
    }
    return x*sign;
}

int main() {
    n_value=get_input(); m_value=get_input();
    int temp_n=n_value, length=-1;
    while (temp_n) {
        length++;
        binary[length]=temp_n%m_value;
        temp_n/=m_value;
    }
    length++;
    MatrixType result, temp;
    memset(result.matrix, 0, sizeof(result.matrix));
    for (int i=0; i<=m_value; ++i) result.matrix[0][i]=1;
    static MatrixType P[MAX_SIZE*2], S[MAX_SIZE*2], A[MAX_SIZE*2];
    for (int i=0; i<=m_value; ++i) {
        for (int j=0; j<=m_value; ++j) {
            A[0][i].matrix[j][j]=1;
        }
    }
    for (int i=0; i<length; ++i) {
        for (int j=0; j<=m_value; ++j) {
            A[i][0].matrix[j][j]=1;
        }
        if (i==0) {
            for (int j=0; j<m_value; ++j) {
                A[i][j].matrix[m_value][m_value]=1;
                for (int k=0; k<m_value; ++k) {
                    if (k!=j) {
                        A[i][j].matrix[k][k]=1;
                        for (int l=0; l<=m_value; ++l) A[i][j].matrix[k][l]=1;
                    }
                }
            }
        } else {
            for (int j=0; j<m_value; ++j) {
                if (j==0) A[i][j]=S[i-1][0];
                else A[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
        P[i][0]=A[i][0];
        for (int j=1; j<m_value; ++j) P[i][j]=P[i][j-1]*A[i][j];
        S[i][m_value-1]=A[i][m_value-1];
        for (int j=m_value-2; j>=0; --j) S[i][j]=A[i][j]*S[i][j+1];
    }
    int j=0;
    for (int i=length-1; i>=0; --i) {
        while (binary[i]>0) {
            result=result*A[i][j]; j++; if (j==m_value) j=0; binary[i]--;
        }
    }
    cout<<result.matrix[0][m_value]<<endl;
}
